  function mergeMessage(message){if(!message?.id)return;const index=state.messages.findIndex(item=>item.id===message.id&&item.direction===message.direction&&item.from===message.from&&item.to===message.to);if(index>=0)state.messages[index]={...state.messages[index],...message};else state.messages.push(message);state.messages.sort((a,b)=>(Number(a.at)||0)-(Number(b.at)||0));state.messages=state.messages.slice(-500);}
  function contactFor(query){return state.contacts.find(item=>String(item.id)===String(query)||item.callsign===callsign(query));}
  function init(hooks={}){if(state.ready)return;state.hooks=hooks;state.contacts=(Array.isArray(settings().console?.contacts)?settings().console.contacts:Array.isArray(load('zapdmr-console-contacts',[]))?load('zapdmr-console-contacts',[]):[]).filter(item=>item&&item.id&&item.callsign).slice(0,250);state.messages=(Array.isArray(load('zapdmr-console-messages',[]))?load('zapdmr-console-messages',[]):[]).filter(item=>item&&item.id).slice(-500);createSettings();createContacts();state.ready=true;bindSettings();if(hooks.platform==='windows'){const panel=$('[data-settings-pane=radio-spp]');panel.querySelector('h3').textContent='Botão PTT série / Bluetooth SPP';panel.querySelector('p').textContent='No Windows, emparelhe o acessório SPP e selecione a porta COM de saída criada pelo sistema.';$('#rcSppRefresh').textContent='Listar portas COM';$('#rcSppSettings').textContent='Atualizar portas COM';$('#rcSppSettings').onclick=()=>run(refreshSpp);}apply();renderConversation();updateStatus(hooks.getStatus?.()||{});log({source:'sistema',message:'Consola de rádio iniciada.'});document.addEventListener('keydown',event=>{if(hooks.platform==='windows'&&window.ZapDMRDesktop&&['F7','F8'].includes(event.code))return;if(event.repeat||['INPUT','TEXTAREA','SELECT'].includes(event.target?.tagName)||event.ctrlKey||event.altKey||event.metaKey)return;if(prefs().scan.key&&event.code===prefs().scan.key){event.preventDefault();if(state.hooks.toggleScan)state.hooks.toggleScan();else $('#scanTalkgroups')?.click();log({source:'tecla',message:'Pesquisa: '+event.code});}});}
  window.ZapDMRConsole={init,apply,updateStatus,log,aprsEvent,updateSpp,openContacts,contactFor,getContacts:()=>state.contacts.slice(),getPreferences:prefs,isLearning:()=>Boolean(state.spp.learning)};
